50	export const PUBLIC_USER_FIELDS = 'u.id, u.name, u.role, u.course_id, u.semester, u.bio, u.avatar_id, u.is_guest, u.created_at';
51	
52	// Middleware: coloca req.user se houver sessão válida.
53	export async function loadUser(req, _res, next) {
54	  const token = readToken(req);
55	  req.user = null;
56	  if (token) {
57	    req.user = await one(
58	      `SELECT ${PUBLIC_USER_FIELDS}, u.email, c.name AS course_name, c.short AS course
59	         FROM sessions s JOIN users u ON u.id = s.user_id LEFT JOIN courses c ON c.id = u.course_id
60	        WHERE s.token = $1 AND s.expires_at > now()`,
61	      [token],
62	    );
63	  }
64	  next();
65	}
66	
67	export function requireUser(req, _res, next) {
68	  if (!req.user) throw new HttpError(401, 'Faça login para continuar.');
69	  next();
70	}
71	
72	// Limite simples de tentativas (por IP) para login e cadastro.
73	const attempts = new Map();
74	export function rateLimit(max = 30, windowMs = 10 * 60 * 1000) {
75	  return (req, _res, next) => {
