function photoSvg(title, emoji, c1, c2, seed) {
  const r = (n) => ((seed * 9301 + n * 49297) % 233280) / 233280;
  const circles = Array.from({ length: 7 }, (_, i) => {
    const cx = Math.round(r(i + 1) * 1080);
    const cy = Math.round(r(i + 11) * 1080);
    const rad = Math.round(60 + r(i + 21) * 260);
    return `<circle cx="${cx}" cy="${cy}" r="${rad}" fill="#fff" opacity="${(0.05 + r(i + 31) * 0.12).toFixed(2)}"/>`;
  }).join('');
  const safe = title.replace(/&/g, '&amp;').replace(/</g, '&lt;');
  return `<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1080" viewBox="0 0 1080 1080">
<defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${c1}"/><stop offset="1" stop-color="${c2}"/></linearGradient></defs>
<rect width="1080" height="1080" fill="url(#g)"/>${circles}
<text x="540" y="560" font-size="360" text-anchor="middle" dominant-baseline="middle">${emoji}</text>
<text x="540" y="910" font-family="Segoe UI, Roboto, Helvetica, Arial, sans-serif" font-size="64" font-weight="700" fill="#fff" text-anchor="middle">${safe}</text>
<text x="540" y="985" font-family="Segoe UI, Roboto, Helvetica, Arial, sans-serif" font-size="36" fill="#fff" opacity=".8" text-anchor="middle">UniMax</text>
</svg>`;
}

export async function seedIfEmpty() {
  const has = await one('SELECT count(*)::int AS n FROM users');
  if (has.n > 0) return false;
  console.log('Banco vazio: criando dados de exemplo...');

  for (const [name, short] of COURSES) {
    await q('INSERT INTO courses (name, short) VALUES ($1, $2) ON CONFLICT (name) DO NOTHING', [name, short]);
  }
  const courses = await q('SELECT id, name FROM courses');
  const courseId = (i) => courses.find((c) => c.name === COURSES[i][0]).id;
  const demoHash = hashPassword(config.demoPassword);

  const admin = await one(
    `INSERT INTO users (email, password_hash, name, role, bio) VALUES ($1, $2, $3, 'admin', $4) RETURNING id, role`,
    ['secretaria@unimax.edu.br', hashPassword(config.adminPassword), 'UniMax — Secretaria', 'Canal oficial da UniMax no Maxx.'],
  );
  const profs = [];
  for (const [name, email, bio] of PROFESSORS) {
    profs.push(await one(
      `INSERT INTO users (email, password_hash, name, role, bio) VALUES ($1, $2, $3, 'professor', $4) RETURNING id, role`,
      [email, demoHash, name, bio],
    ));
  }
  const students = [];
  for (const [name, email, ci, sem, bio] of STUDENTS) {
    students.push(await one(
      `INSERT INTO users (email, password_hash, name, role, course_id, semester, bio)
       VALUES ($1, $2, $3, 'aluno', $4, $5, $6) RETURNING id, role`,
      [email, demoHash, name, courseId(ci), sem, bio],
    ));
  }

  // Fotos
  for (let i = 0; i < PHOTOS.length; i++) {
    const [si, title, emoji, c1, c2, caption] = PHOTOS[i];
    const imgId = await saveImage('image/svg+xml', Buffer.from(photoSvg(title, emoji, c1, c2, i + 3)), students[si].id);
    const post = await one(
      "INSERT INTO posts (user_id, kind, image_id, caption) VALUES ($1, 'foto', $2, $3) RETURNING id",
      [students[si].id, imgId, caption],
    );
    await q("INSERT INTO points (user_id, amount, kind, ref) VALUES ($1, 10, 'post', $2)", [students[si].id, `post:${post.id}`]);
    await checkTrophies(students[si].id);
  }

  // Medalhas (geram posts de conquista e pontos)
  for (const [pi, si, type, reason] of MEDALS) {
    await giveMedal(profs[pi], { student_id: students[si].id, type, reason });
  }

  // Curtidas e comentários (determinísticos para o resultado ser sempre o mesmo)
  const everyone = [...students, ...profs];
  const allPosts = await q('SELECT id, user_id FROM posts ORDER BY id');
  for (let pi = 0; pi < allPosts.length; pi++) {
    const p = allPosts[pi];
    const nLikes = 3 + ((pi * 7) % 9);
    for (let k = 0; k < nLikes; k++) {
      const liker = everyone[(pi * 5 + k * 3) % everyone.length];
      if (liker.id === p.user_id) continue;
      const existing = await one('SELECT 1 FROM likes WHERE post_id = $1 AND user_id = $2', [p.id, liker.id]);
      if (!existing) await toggleLike(liker, p.id);
    }
    const nComments = (pi * 3) % 4;
    for (let k = 0; k < nComments; k++) {
      const who = everyone[(pi * 11 + k * 7) % everyone.length];
      if (who.id === p.user_id) continue;
      await addComment(who, p.id, COMMENTS[(pi + k) % COMMENTS.length]);
    }
  }

  // Algumas curtidas nos troféus que surgiram durante a semeadura (para não ficarem zerados).
  const trophyPosts = await q("SELECT id, user_id FROM posts WHERE kind = 'trofeu' AND id > $1 ORDER BY id", [allPosts[allPosts.length - 1].id]);
  for (let ti = 0; ti < trophyPosts.length; ti++) {
    const p = trophyPosts[ti];
    for (let k = 0; k < 2 + (ti % 4); k++) {
      const liker = everyone[(ti * 3 + k * 5 + 1) % everyone.length];
      if (liker.id === p.user_id) continue;
      const existing = await one('SELECT 1 FROM likes WHERE post_id = $1 AND user_id = $2', [p.id, liker.id]);
      if (!existing) await toggleLike(liker, p.id);
    }
  }

  // Avisos
  for (const [pi, title, body, ci, pinned] of NOTICES) {
    const author = pi === null ? admin : profs[pi];
    await q('INSERT INTO notices (author_id, title, body, course_id, pinned) VALUES ($1, $2, $3, $4, $5)', [
      author.id, title, body, ci === null ? null : courseId(ci), pinned,
    ]);
  }

  // Espalha as datas para o feed parecer de verdade (posts mais antigos = mais horas atrás).
  // Fotos e medalhas se intercalam (embaralhamento fixo); a mais nova é sempre uma foto.
  await q(`UPDATE posts p SET created_at = now() - (r.rn - 1) * interval '4 hours' - interval '20 minutes'
             FROM (SELECT id, row_number() OVER (ORDER BY (kind = 'foto' AND id = (SELECT max(id) FROM posts WHERE kind = 'foto')) DESC,
                                                         (id * 37) % 101) AS rn
                     FROM posts WHERE kind <> 'trofeu') r
            WHERE r.id = p.id`);
  await q(`UPDATE posts SET created_at = now() - (id % 19) * interval '5 hours' - interval '3 hours 10 minutes' WHERE kind = 'trofeu'`);
  await q(`UPDATE user_trophies t SET unlocked_at = p.created_at FROM posts p WHERE p.kind = 'trofeu' AND p.user_id = t.user_id AND p.ref_code = t.code`);
  await q(`UPDATE medals m SET created_at = p.created_at FROM posts p WHERE p.kind = 'medalha' AND p.ref_id = m.id`);
  await q(`UPDATE notices SET created_at = now() - ((SELECT max(id) FROM notices) - id) * interval '1 day' - interval '2 hours'`);

  console.log(`Dados de exemplo criados: ${students.length} alunos, ${profs.length} professores, ${PHOTOS.length} fotos.`);
  return true;
}

