89	function photoSvg(title, emoji, c1, c2, seed) {
90	  const r = (n) => ((seed * 9301 + n * 49297) % 233280) / 233280;
91	  const circles = Array.from({ length: 7 }, (_, i) => {
92	    const cx = Math.round(r(i + 1) * 1080);
93	    const cy = Math.round(r(i + 11) * 1080);
94	    const rad = Math.round(60 + r(i + 21) * 260);
95	    return `<circle cx="${cx}" cy="${cy}" r="${rad}" fill="#fff" opacity="${(0.05 + r(i + 31) * 0.12).toFixed(2)}"/>`;
96	  }).join('');
97	  const safe = title.replace(/&/g, '&amp;').replace(/</g, '&lt;');
98	  return `<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1080" viewBox="0 0 1080 1080">
99	<defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${c1}"/><stop offset="1" stop-color="${c2}"/></linearGradient></defs>
100	<rect width="1080" height="1080" fill="url(#g)"/>${circles}
101	<text x="540" y="560" font-size="360" text-anchor="middle" dominant-baseline="middle">${emoji}</text>
102	<text x="540" y="910" font-family="Segoe UI, Roboto, Helvetica, Arial, sans-serif" font-size="64" font-weight="700" fill="#fff" text-anchor="middle">${safe}</text>
103	<text x="540" y="985" font-family="Segoe UI, Roboto, Helvetica, Arial, sans-serif" font-size="36" fill="#fff" opacity=".8" text-anchor="middle">UniMax</text>
104	</svg>`;
105	}
