107	export async function seedIfEmpty() {
108	  const has = await one('SELECT count(*)::int AS n FROM users');
109	  if (has.n > 0) return false;
110	  console.log('Banco vazio: criando dados de exemplo...');
111	
112	  for (const [name, short] of COURSES) {
113	    await q('INSERT INTO courses (name, short) VALUES ($1, $2) ON CONFLICT (name) DO NOTHING', [name, short]);
114	  }
115	  const courses = await q('SELECT id, name FROM courses');
116	  const courseId = (i) => courses.find((c) => c.name === COURSES[i][0]).id;
117	  const demoHash = hashPassword(config.demoPassword);
118	
119	  const admin = await one(
120	    `INSERT INTO users (email, password_hash, name, role, bio) VALUES ($1, $2, $3, 'admin', $4) RETURNING id, role`,
121	    ['secretaria@unimax.edu.br', hashPassword(config.adminPassword), 'UniMax — Secretaria', 'Canal oficial da UniMax no Maxx.'],
122	  );
123	  const profs = [];
124	  for (const [name, email, bio] of PROFESSORS) {
125	    profs.push(await one(
126	      `INSERT INTO users (email, password_hash, name, role, bio) VALUES ($1, $2, $3, 'professor', $4) RETURNING id, role`,
127	      [email, demoHash, name, bio],
128	    ));
129	  }
130	  const students = [];
131	  for (const [name, email, ci, sem, bio] of STUDENTS) {
132	    students.push(await one(
133	      `INSERT INTO users (email, password_hash, name, role, course_id, semester, bio)
134	       VALUES ($1, $2, $3, 'aluno', $4, $5, $6) RETURNING id, role`,
135	      [email, demoHash, name, courseId(ci), sem, bio],
136	    ));
137	  }
138	
139	  // Fotos
140	  for (let i = 0; i < PHOTOS.length; i++) {
141	    const [si, title, emoji, c1, c2, caption] = PHOTOS[i];
142	    const imgId = await saveImage('image/svg+xml', Buffer.from(photoSvg(title, emoji, c1, c2, i + 3)), students[si].id);
143	    const post = await one(
144	      "INSERT INTO posts (user_id, kind, image_id, caption) VALUES ($1, 'foto', $2, $3) RETURNING id",
145	      [students[si].id, imgId, caption],
146	    );
147	    await q("INSERT INTO points (user_id, amount, kind, ref) VALUES ($1, 10, 'post', $2)", [students[si].id, `post:${post.id}`]);
148	    await checkTrophies(students[si].id);
149	  }
150	
151	  // Medalhas (geram posts de conquista e pontos)
152	  for (const [pi, si, type, reason] of MEDALS) {
153	    await giveMedal(profs[pi], { student_id: students[si].id, type, reason });
154	  }
155	
156	  // Curtidas e comentários (determinísticos para o resultado ser sempre o mesmo)
157	  const everyone = [...students, ...profs];
158	  const allPosts = await q('SELECT id, user_id FROM posts ORDER BY id');
159	  for (let pi = 0; pi < allPosts.length; pi++) {
160	    const p = allPosts[pi];
161	    const nLikes = 3 + ((pi * 7) % 9);
162	    for (let k = 0; k < nLikes; k++) {
163	      const liker = everyone[(pi * 5 + k * 3) % everyone.length];
164	      if (liker.id === p.user_id) continue;
165	      const existing = await one('SELECT 1 FROM likes WHERE post_id = $1 AND user_id = $2', [p.id, liker.id]);
166	      if (!existing) await toggleLike(liker, p.id);
167	    }
168	    const nComments = (pi * 3) % 4;
169	    for (let k = 0; k < nComments; k++) {
170	      const who = everyone[(pi * 11 + k * 7) % everyone.length];
171	      if (who.id === p.user_id) continue;
172	      await addComment(who, p.id, COMMENTS[(pi + k) % COMMENTS.length]);
173	    }
174	  }
175	
176	  // Algumas curtidas nos troféus que surgiram durante a semeadura (para não ficarem zerados).
177	  const trophyPosts = await q("SELECT id, user_id FROM posts WHERE kind = 'trofeu' AND id > $1 ORDER BY id", [allPosts[allPosts.length - 1].id]);
178	  for (let ti = 0; ti < trophyPosts.length; ti++) {
179	    const p = trophyPosts[ti];
180	    for (let k = 0; k < 2 + (ti % 4); k++) {
181	      const liker = everyone[(ti * 3 + k * 5 + 1) % everyone.length];
182	      if (liker.id === p.user_id) continue;
183	      const existing = await one('SELECT 1 FROM likes WHERE post_id = $1 AND user_id = $2', [p.id, liker.id]);
184	      if (!existing) await toggleLike(liker, p.id);
185	    }
186	  }
187	
188	  // Avisos
189	  for (const [pi, title, body, ci, pinned] of NOTICES) {
190	    const author = pi === null ? admin : profs[pi];
191	    await q('INSERT INTO notices (author_id, title, body, course_id, pinned) VALUES ($1, $2, $3, $4, $5)', [
192	      author.id, title, body, ci === null ? null : courseId(ci), pinned,
193	    ]);
194	  }
195	
196	  // Espalha as datas para o feed parecer de verdade (posts mais antigos = mais horas atrás).
197	  // Fotos e medalhas se intercalam (embaralhamento fixo); a mais nova é sempre uma foto.
198	  await q(`UPDATE posts p SET created_at = now() - (r.rn - 1) * interval '4 hours' - interval '20 minutes'
199	             FROM (SELECT id, row_number() OVER (ORDER BY (kind = 'foto' AND id = (SELECT max(id) FROM posts WHERE kind = 'foto')) DESC,
200	                                                         (id * 37) % 101) AS rn
201	                     FROM posts WHERE kind <> 'trofeu') r
202	            WHERE r.id = p.id`);
203	  await q(`UPDATE posts SET created_at = now() - (id % 19) * interval '5 hours' - interval '3 hours 10 minutes' WHERE kind = 'trofeu'`);
204	  await q(`UPDATE user_trophies t SET unlocked_at = p.created_at FROM posts p WHERE p.kind = 'trofeu' AND p.user_id = t.user_id AND p.ref_code = t.code`);
205	  await q(`UPDATE medals m SET created_at = p.created_at FROM posts p WHERE p.kind = 'medalha' AND p.ref_id = m.id`);
206	  await q(`UPDATE notices SET created_at = now() - ((SELECT max(id) FROM notices) - id) * interval '1 day' - interval '2 hours'`);
207	
208	  console.log(`Dados de exemplo criados: ${students.length} alunos, ${profs.length} professores, ${PHOTOS.length} fotos.`);
209	  return true;
210	}
