131	async function resizeImage(file, max = 1080, quality = 0.82) {
132	  if (!file || !file.type.startsWith('image/')) throw new Error('Escolha um arquivo de imagem.');
133	  const url = URL.createObjectURL(file);
134	  try {
135	    const img = await new Promise((resolve, reject) => {
136	      const i = new Image();
137	      i.onload = () => resolve(i);
138	      i.onerror = () => reject(new Error('Não consegui abrir essa imagem. Tente outra (JPG ou PNG).'));
139	      i.src = url;
140	    });
141	    const scale = Math.min(1, max / Math.max(img.naturalWidth, img.naturalHeight));
142	    const canvas = document.createElement('canvas');
143	    canvas.width = Math.round(img.naturalWidth * scale);
144	    canvas.height = Math.round(img.naturalHeight * scale);
145	    const ctx = canvas.getContext('2d');
146	    ctx.fillStyle = '#fff';
147	    ctx.fillRect(0, 0, canvas.width, canvas.height);
148	    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
149	    return canvas.toDataURL('image/jpeg', quality);
150	  } finally {
151	    URL.revokeObjectURL(url);
152	  }
153	}
